namespace sv_85f7d0e1896d4c0aa2e9fba82c8b7e7f.Client.Models;

public class ShipmentDetails
{
    public string TrackingNumber { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTimeOffset EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = [];
}

public class StatusUpdate
{
    public string Description { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTimeOffset Timestamp { get; set; }
}

using sv_85f7d0e1896d4c0aa2e9fba82c8b7e7f.Client.Models;

namespace sv_85f7d0e1896d4c0aa2e9fba82c8b7e7f.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net;
using System.Net.Http.Json;
using sv_85f7d0e1896d4c0aa2e9fba82c8b7e7f.Client.Models;

namespace sv_85f7d0e1896d4c0aa2e9fba82c8b7e7f.Client.Services;

public class ClientShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            return null;
        }

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

